const mongoose = require('mongoose');

// Stage 5: every document that comes from a dataset says which KIND of data it is (CLAUDE.md, "Data and
// results honesty"):
//  - real:      data from real people (none is loaded yet; WildChat would be the first)
//  - benchmark: a published benchmark such as LoCoMo, used for accuracy results
//  - synthetic: generated by our own script, used ONLY for performance and scale numbers
// Documents created through the API have no label: they are the app's own data, not a dataset.
const DATASETS = ['real', 'benchmark', 'synthetic'];

const datasetField = {
  type: String,
  enum: { values: DATASETS, message: `dataset must be one of: ${DATASETS.join(', ')}` },
  default: undefined,
};

// Where a loaded document came from: the dataset's name and the ORIGINAL id inside it, so any row can be
// traced back to the source file (and results can quote the benchmark's own ids).
const sourceSchema = new mongoose.Schema(
  {
    name: { type: String, required: true, trim: true }, // e.g. 'locomo', 'synthetic-scale'
    id: { type: String, trim: true }, // e.g. LoCoMo sample_id 'conv-26' or dialog id 'D1:3'
    session: { type: Number }, // LoCoMo session number (conversations only)
    speaker: { type: String, trim: true }, // the original speaker name (messages only)
    date: { type: Date }, // the session timestamp given by the dataset (conversations only)
  },
  { _id: false }
);

module.exports = { DATASETS, datasetField, sourceSchema };
